CREATE TABLE `customerorders` (
  `Id` int(11) NOT NULL AUTO_INCREMENT,
  `OrderCode` longtext NOT NULL,
  `PaymentMethod` longtext NOT NULL,
  `InsertByUserId` int(11) NOT NULL,
  `TableId` int(11) DEFAULT NULL,
  `ReservationId` int(11) DEFAULT NULL,
  `OrderType` longtext NOT NULL,
  `InsertDate` datetime(6) NOT NULL,
  `UpdateDate` datetime(6) NOT NULL,
  `IsDeleted` tinyint(1) NOT NULL,
  `Notes` longtext DEFAULT NULL,
  `DailySequenceNumber` int(11) DEFAULT NULL,
  `OrderStatus` longtext NOT NULL,
  `PaymentStatus` longtext NOT NULL,
  `DeliveryAddress` longtext DEFAULT NULL,
  `DeliveryAssignedAt` datetime(6) DEFAULT NULL,
  `DeliveryCompletedAt` datetime(6) DEFAULT NULL,
  `DeliveryCustomerName` longtext DEFAULT NULL,
  `DeliveryDriverId` int(11) DEFAULT NULL,
  `DeliveryFee` decimal(65,30) DEFAULT NULL,
  `DeliveryPhoneNumber` longtext DEFAULT NULL,
  `DeliveryStatus` longtext DEFAULT NULL,
  `PagerNumber` longtext DEFAULT NULL,
  `DeliveryPointsEarned` int(11) DEFAULT NULL,
  `LoyaltyProgramId` int(11) DEFAULT NULL,
  `DiscountAmount` decimal(65,30) DEFAULT NULL,
  `DiscountPercent` decimal(65,30) DEFAULT NULL,
  `DiscountType` longtext DEFAULT NULL,
  `DiscountValue` decimal(65,30) DEFAULT NULL,
  `OrderSubTotal` decimal(65,30) DEFAULT NULL,
  `OrderTotalAfterDiscount` decimal(65,30) DEFAULT NULL,
  `NumberOfGuests` int(11) DEFAULT NULL,
  `CreditCustomerId` int(11) DEFAULT NULL,
  `CreditEmployeeId` int(11) DEFAULT NULL,
  PRIMARY KEY (`Id`),
  KEY `IX_CustomerOrders_InsertByUserId` (`InsertByUserId`),
  KEY `IX_CustomerOrders_ReservationId` (`ReservationId`),
  KEY `IX_CustomerOrders_TableId` (`TableId`),
  KEY `IX_CustomerOrders_DeliveryDriverId` (`DeliveryDriverId`),
  KEY `IX_CustomerOrders_LoyaltyProgramId` (`LoyaltyProgramId`),
  KEY `IX_CustomerOrders_CreditCustomerId` (`CreditCustomerId`),
  KEY `IX_CustomerOrders_CreditEmployeeId` (`CreditEmployeeId`),
  CONSTRAINT `FK_CustomerOrders_Customers_CreditCustomerId` FOREIGN KEY (`CreditCustomerId`) REFERENCES `customers` (`Id`) ON DELETE SET NULL,
  CONSTRAINT `FK_CustomerOrders_DeliveryDrivers_DeliveryDriverId` FOREIGN KEY (`DeliveryDriverId`) REFERENCES `deliverydrivers` (`Id`) ON DELETE SET NULL,
  CONSTRAINT `FK_CustomerOrders_Employees_CreditEmployeeId` FOREIGN KEY (`CreditEmployeeId`) REFERENCES `employees` (`Id`) ON DELETE SET NULL,
  CONSTRAINT `FK_CustomerOrders_LoyaltyPrograms_LoyaltyProgramId` FOREIGN KEY (`LoyaltyProgramId`) REFERENCES `loyaltyprograms` (`Id`) ON DELETE SET NULL,
  CONSTRAINT `FK_CustomerOrders_Reservations_ReservationId` FOREIGN KEY (`ReservationId`) REFERENCES `reservations` (`Id`) ON DELETE SET NULL,
  CONSTRAINT `FK_CustomerOrders_Tables_TableId` FOREIGN KEY (`TableId`) REFERENCES `tables` (`Id`) ON DELETE SET NULL,
  CONSTRAINT `FK_CustomerOrders_Users_InsertByUserId` FOREIGN KEY (`InsertByUserId`) REFERENCES `users` (`Id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=906 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
